INSERT OR IGNORE INTO kursus (id, kode, judul, subjudul, deskripsi, kategori, estimasi, nilai_lulus_akhir, durasi_akhir_menit, jumlah_soal_akhir, level, sasaran_json, hasil_belajar_json, durasi_menit, gambar_url, is_published, urutan) VALUES ('membaca-data-bps', 'MDB-2026', 'Membaca Data BPS untuk Perencanaan Daerah', 'Dari angka di tabel menjadi dasar keputusan', 'Kursus dasar untuk memahami asal data BPS, membaca persentase, rasio, dan tren, lalu memakainya dalam perencanaan daerah. Cocok untuk ASN, pelajar, masyarakat umum, dan mitra BPS.', 'Literasi Data', 'Sekitar 1,5 jam', 80, 30, 6, 'dasar', '["asn","umum","pelajar","mitra"]', '["Membedakan data, statistik, dan indikator serta sumbernya: sensus, survei, dan data administrasi.","Membaca persentase, rasio, dan perubahan angka dengan satuan yang benar.","Mengajukan pertanyaan kritis tentang sumber, periode, dan cara hitung sebelum memakai angka.","Memakai indikator per kecamatan untuk menyusun dasar pertimbangan perencanaan."]', 0, '/gambar/kursus-contoh.svg', 1, 50);
