INSERT OR IGNORE INTO pelajaran (id, bab_id, urutan, judul, jenis, isi_json, durasi_menit, wajib) VALUES (200101, 2001, 1, 'Video: mengenal sumber dan peran data ekonomi', 'video', '{"url":"https://www.youtube-nocookie.com/embed/tUXqJ1xyqIk"}', 15, 1);
INSERT OR IGNORE INTO pelajaran (id, bab_id, urutan, judul, jenis, isi_json, durasi_menit, wajib) VALUES (200102, 2001, 2, 'Bacaan: data, statistik, dan indikator', 'bacaan', '{"markdown":"## Apa itu data, statistik, dan indikator?\n\n**Data** adalah catatan fakta yang belum diolah, misalnya jumlah penduduk satu kecamatan. **Statistik** adalah hasil pengolahan data menjadi ringkasan yang bermakna. **Indikator** adalah ukuran terpilih untuk memantau suatu keadaan dari waktu ke waktu, misalnya tingkat pengangguran terbuka.\n\n## Dari mana data BPS berasal?\n\n- **Sensus**: pencacahan lengkap terhadap seluruh populasi, dilakukan berkala.\n- **Survei**: pencacahan terhadap sampel yang dipilih secara ilmiah, lalu hasilnya diperluas untuk menggambarkan populasi.\n- **Kompilasi produk administrasi**: pemanfaatan catatan instansi lain, seperti data sekolah atau data kependudukan.\n\n## Empat pertanyaan sebelum memakai angka\n\n1. Siapa yang menerbitkan angka ini, dan kapan?\n2. Apa satuannya: jiwa, persen, rupiah, atau per 1.000 penduduk?\n3. Wilayah dan periode mana yang dicakup?\n4. Bagaimana cara menghitungnya?\n\nJawaban pertanyaan terakhir biasanya ada pada **metadata** atau catatan teknis di bawah tabel."}', 8, 1);
INSERT OR IGNORE INTO pelajaran (id, bab_id, urutan, judul, jenis, isi_json, durasi_menit, wajib) VALUES (200103, 2001, 3, 'Latihan: istilah dasar', 'latihan', '{"petunjuk":"Jawab tiga soal singkat. Latihan boleh diulang sampai nilai minimal tercapai.","nilai_lulus":60}', 5, 1);
INSERT OR IGNORE INTO pelajaran (id, bab_id, urutan, judul, jenis, isi_json, durasi_menit, wajib) VALUES (200201, 2002, 1, 'Bacaan: persentase, rasio, dan tren', 'bacaan', '{"markdown":"## Persentase\n\nPersentase menyatakan bagian terhadap keseluruhan: **bagian ÷ keseluruhan × 100**. Bila 45 dari 60 desa memiliki suatu fasilitas, persentasenya 45 ÷ 60 × 100 = 75 persen.\n\n## Rasio\n\nRasio membandingkan dua besaran yang berbeda, misalnya jumlah murid per guru. Bila ada 360 murid dan 24 guru, rasionya 15 murid per guru. Rasio tidak selalu bernilai 100 atau kurang.\n\n## Perubahan angka\n\nAda dua cara menyatakan perubahan:\n\n- **Poin persentase**: selisih dua persentase. Dari 8 persen menjadi 10 persen berarti naik 2 poin persentase.\n- **Persen perubahan**: selisih dibagi nilai awal. Pada contoh yang sama, 2 ÷ 8 × 100 = 25 persen.\n\nKedua cara itu benar, tetapi artinya berbeda. Tulislah dengan jelas yang mana yang dipakai.\n\n## Membaca tren\n\n- Bandingkan periode yang sebanding, misalnya triwulan dengan triwulan yang sama tahun lalu.\n- Pastikan definisi dan cara hitung tidak berubah di antara dua titik waktu.\n- Satu titik naik atau turun belum tentu sebuah tren; lihat beberapa periode."}', 10, 1);
INSERT OR IGNORE INTO pelajaran (id, bab_id, urutan, judul, jenis, isi_json, durasi_menit, wajib) VALUES (200202, 2002, 2, 'Dokumen: publikasi resmi BPS', 'pdf', '{"url":"https://www.bps.go.id/id/publication","penerbit":"BPS"}', 10, 0);
INSERT OR IGNORE INTO pelajaran (id, bab_id, urutan, judul, jenis, isi_json, durasi_menit, wajib) VALUES (200203, 2002, 3, 'Latihan: menghitung dan membaca angka', 'latihan', '{"petunjuk":"Hitung dengan teliti. Boleh memakai kalkulator.","nilai_lulus":60}', 8, 1);
INSERT OR IGNORE INTO pelajaran (id, bab_id, urutan, judul, jenis, isi_json, durasi_menit, wajib) VALUES (200301, 2003, 1, 'Video: mengapa data dikumpulkan', 'video', '{"url":"https://www.youtube-nocookie.com/embed/L86LTnOeXQE"}', 5, 1);
INSERT OR IGNORE INTO pelajaran (id, bab_id, urutan, judul, jenis, isi_json, durasi_menit, wajib) VALUES (200302, 2003, 2, 'Bacaan: dari data ke keputusan', 'bacaan', '{"markdown":"## Dari data ke keputusan\n\n1. **Rumuskan pertanyaan kebijakan.** Misalnya: kecamatan mana yang paling memerlukan tambahan fasilitas kesehatan?\n2. **Pilih indikator yang relevan.** Cari indikator yang benar-benar menjawab pertanyaan itu, bukan yang kebetulan tersedia.\n3. **Bandingkan dengan wajar.** Bandingkan antarwilayah dan antarwaktu dengan satuan, tahun, dan cara hitung yang sama.\n4. **Periksa arah indikator.** Pada sebagian indikator nilai tinggi itu baik, pada yang lain nilai rendah yang baik.\n5. **Catat keterbatasan dan sumber.** Tulis sumber, tahun, dan catatan agar orang lain dapat menelusuri kembali.\n\n## Contoh di SIKOP\n\nPeta Tematik menampilkan indikator per kecamatan. Setiap kartu mencantumkan sumber, tahun, dan cara hitung. Data ditampilkan sebagai agregat kecamatan, tanpa rincian per desa atau per individu. Gunakan peringkat dan pembanding kabupaten untuk melihat posisi sebuah kecamatan, lalu baca catatan cara hitung sebelum menyimpulkan."}', 8, 1);
INSERT OR IGNORE INTO pelajaran (id, bab_id, urutan, judul, jenis, isi_json, durasi_menit, wajib) VALUES (200303, 2003, 3, 'Latihan: memakai indikator', 'latihan', '{"petunjuk":"Pilih jawaban yang paling tepat untuk situasi perencanaan.","nilai_lulus":60}', 5, 1);
