INSERT OR IGNORE INTO soal (id, kursus_id, modul_id, jenis, urutan, pertanyaan, opsi_json, kunci, pembahasan, is_active) VALUES (20026, 'membaca-data-bps', NULL, 'akhir', 8, 'Sebelum menyebut nilai tinggi sebagai hal buruk atau baik, periksa...', '[{"id":"A","text":"Warna latar"},{"id":"B","text":"Ukuran peta"},{"id":"C","text":"Arah indikator"},{"id":"D","text":"Jenis huruf"}]', 'C', 'Arah indikator menentukan makna nilai tinggi.', 1);
INSERT OR IGNORE INTO soal_latihan (id, pelajaran_id, urutan, pertanyaan, opsi_json, kunci, pembahasan, is_active) VALUES (2001, 200103, 1, 'Pencacahan terhadap seluruh anggota populasi disebut...', '[{"id":"A","text":"Sensus"},{"id":"B","text":"Survei"},{"id":"C","text":"Penarikan sampel"},{"id":"D","text":"Kompilasi produk administrasi"}]', 'A', 'Sensus mencacah seluruh populasi, sedangkan survei hanya mencacah sampel.', 1);
INSERT OR IGNORE INTO soal_latihan (id, pelajaran_id, urutan, pertanyaan, opsi_json, kunci, pembahasan, is_active) VALUES (2002, 200103, 2, 'Ukuran terpilih yang dipakai untuk memantau suatu keadaan dari waktu ke waktu disebut...', '[{"id":"A","text":"Metadata"},{"id":"B","text":"Indikator"},{"id":"C","text":"Sampel"},{"id":"D","text":"Responden"}]', 'B', 'Indikator memudahkan pemantauan, misalnya tingkat pengangguran terbuka.', 1);
INSERT OR IGNORE INTO soal_latihan (id, pelajaran_id, urutan, pertanyaan, opsi_json, kunci, pembahasan, is_active) VALUES (2003, 200103, 3, 'Data jumlah siswa yang dicatat oleh dinas pendidikan lalu dimanfaatkan BPS termasuk sumber...', '[{"id":"A","text":"Sensus penduduk"},{"id":"B","text":"Survei rumah tangga"},{"id":"C","text":"Produk administrasi"},{"id":"D","text":"Wawancara telepon"}]', 'C', 'Catatan rutin instansi lain yang dimanfaatkan BPS disebut produk administrasi.', 1);
INSERT OR IGNORE INTO soal_latihan (id, pelajaran_id, urutan, pertanyaan, opsi_json, kunci, pembahasan, is_active) VALUES (2004, 200203, 1, 'Sebanyak 45 dari 60 desa memiliki suatu fasilitas. Berapa persentasenya?', '[{"id":"A","text":"45 persen"},{"id":"B","text":"60 persen"},{"id":"C","text":"85 persen"},{"id":"D","text":"75 persen"}]', 'D', '45 ÷ 60 × 100 = 75.', 1);
INSERT OR IGNORE INTO soal_latihan (id, pelajaran_id, urutan, pertanyaan, opsi_json, kunci, pembahasan, is_active) VALUES (2005, 200203, 2, 'Sebuah angka naik dari 8 persen menjadi 10 persen. Kenaikannya adalah...', '[{"id":"A","text":"2 poin persentase"},{"id":"B","text":"2 persen"},{"id":"C","text":"10 poin persentase"},{"id":"D","text":"8 poin persentase"}]', 'A', 'Selisih dua persentase dinyatakan dalam poin persentase: 10 - 8 = 2.', 1);
INSERT OR IGNORE INTO soal_latihan (id, pelajaran_id, urutan, pertanyaan, opsi_json, kunci, pembahasan, is_active) VALUES (2006, 200203, 3, 'Ada 360 murid dan 24 guru. Berapa rasio murid per guru?', '[{"id":"A","text":"12"},{"id":"B","text":"15"},{"id":"C","text":"24"},{"id":"D","text":"360"}]', 'B', '360 ÷ 24 = 15 murid per guru.', 1);
INSERT OR IGNORE INTO soal_latihan (id, pelajaran_id, urutan, pertanyaan, opsi_json, kunci, pembahasan, is_active) VALUES (2007, 200303, 1, 'Langkah pertama memakai data untuk perencanaan adalah...', '[{"id":"A","text":"Memilih grafik yang menarik"},{"id":"B","text":"Mengunduh seluruh tabel yang ada"},{"id":"C","text":"Merumuskan pertanyaan kebijakan"},{"id":"D","text":"Menulis kesimpulan"}]', 'C', 'Pertanyaan kebijakan menentukan indikator yang relevan.', 1);
INSERT OR IGNORE INTO soal_latihan (id, pelajaran_id, urutan, pertanyaan, opsi_json, kunci, pembahasan, is_active) VALUES (2008, 200303, 2, 'Mengapa tahun dan cara hitung perlu diperiksa sebelum membandingkan dua angka?', '[{"id":"A","text":"Agar angka tampak lebih besar"},{"id":"B","text":"Agar tabel lebih rapi"},{"id":"C","text":"Agar tidak perlu menyebut sumber"},{"id":"D","text":"Agar perbandingan sebanding"}]', 'D', 'Perbandingan hanya adil bila definisi, periode, dan cara hitung sama.', 1);
INSERT OR IGNORE INTO soal_latihan (id, pelajaran_id, urutan, pertanyaan, opsi_json, kunci, pembahasan, is_active) VALUES (2009, 200303, 3, 'Peta menampilkan warna lebih gelap untuk nilai lebih tinggi. Apa yang diperiksa sebelum menyimpulkan sebuah kecamatan lebih buruk?', '[{"id":"A","text":"Arah indikator"},{"id":"B","text":"Warna latar peta"},{"id":"C","text":"Jumlah label"},{"id":"D","text":"Ukuran huruf"}]', 'A', 'Nilai tinggi baik untuk sebagian indikator, tetapi buruk untuk yang lain.', 1);
